  GRAPH <http://ops-sys.local/ontology#graph/semantic/claude-proyectos/amphora-style-md> {
    <http://ops-sys.local/ontology#concept/amphora-style> rdf:type ops:Concept ;
      ops:name "amphora style" ;
      ops:conceptType "concept" ;
      ops:summary "Pencil-and-wash history look on parchment, framed top and bottom by amphora friezes in brown ink." ;
      ops:sourceDoc "amphora/STYLE.md" .
    <http://ops-sys.local/ontology#concept/friezes> rdf:type ops:Concept ;
      ops:name "Friezes" ;
      ops:conceptType "component" ;
      ops:summary "Opaque 190px parchment bands with ink teeth, rules and a running key, framing the picture top and bottom." ;
      ops:sourceDoc "amphora/STYLE.md" .
    <http://ops-sys.local/ontology#concept/parchment-ground> rdf:type ops:Concept ;
      ops:name "Parchment ground" ;
      ops:conceptType "component" ;
      ops:summary "Warm parchment background with cloud stains, tide rings, fibres and grain." ;
      ops:sourceDoc "amphora/STYLE.md" .
    <http://ops-sys.local/ontology#concept/ink-line> rdf:type ops:Concept ;
      ops:name "Ink line" ;
      ops:conceptType "component" ;
      ops:summary "Thin brown ink stroke (about 2.2px) with a gentle boil, used for all drawing." ;
      ops:sourceDoc "amphora/STYLE.md" .
    <http://ops-sys.local/ontology#concept/wash-fill> rdf:type ops:Concept ;
      ops:name "Wash fill" ;
      ops:conceptType "component" ;
      ops:summary "Flat watercolour wash with upper-left light, pooled edges, paper texture and cloth hatching." ;
      ops:sourceDoc "amphora/STYLE.md" .
    <http://ops-sys.local/ontology#concept/side-colour-coding> rdf:type ops:Concept ;
