    <http://ops-sys.local/ontology#concept/cartoon3d> rdf:type ops:Concept ;
      ops:name "cartoon3d" ;
      ops:conceptType "concept" ;
      ops:summary "3D cartoon shorts: flat 2D cut-out people placed in dense, glossy, warmly lit 3D sets, telling second-person true stories with a camera that never stops." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/reference-matching> rdf:type ops:Concept ;
      ops:name "Reference matching" ;
      ops:conceptType "decision" ;
      ops:summary "Goal is to replicate the 7 reference animations as closely as possible; references override the tutorial where they disagree, and Creatorize is not used." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/flow-2d-cut-outs> rdf:type ops:Concept ;
      ops:name "Flow 2D cut-outs" ;
      ops:conceptType "process" ;
      ops:summary "People are 2D cut-out layers generated in Google Flow from reference crops, then sliced into sprites with the green background keyed out." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/3d-sets> rdf:type ops:Concept ;
      ops:name "3D sets" ;
      ops:conceptType "component" ;
