      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/kit-api> rdf:type ops:Concept ;
      ops:name "Kit API" ;
      ops:conceptType "tool" ;
      ops:summary "kit.js helpers (c3Person, c3PersonPose, c3FaceAt, c3Render, c3Subtitle and others) used to build and render scenes." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/voice-pipeline> rdf:type ops:Concept ;
      ops:name "Voice pipeline" ;
      ops:conceptType "process" ;
      ops:summary "tools/trim_voice.py trims pauses and breaths from the voice and writes words.json for timing sync." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/shot-timing> rdf:type ops:Concept ;
      ops:name "Shot timing" ;
      ops:conceptType "concept" ;
      ops:summary "One clause per shot, a new stimulus about every 1.1 s, dissolves of 6 to 13 frames, and the camera moving in most frames." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/face-swap> rdf:type ops:Concept ;
      ops:name "Face swap" ;
      ops:conceptType "process" ;
      ops:summary "Faces change via half-lid, closed and new-face frames about every 1.2 s, with no lip-sync." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/subtitles> rdf:type ops:Concept ;
      ops:name "Subtitles" ;
      ops:conceptType "component" ;
      ops:summary "One heavy white word at a time with a dark outline, placed at about 71% of frame height." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/facts-as-objects> rdf:type ops:Concept ;
      ops:name "Facts as objects" ;
      ops:conceptType "concept" ;
      ops:summary "Numbers appear as physical props (LED counter, gauge, calendar) that land on the word that states them." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/sound-design> rdf:type ops:Concept ;
      ops:name "Sound design" ;
      ops:conceptType "process" ;
      ops:summary "SFX at 12 to 20 per minute tied to visible actions, a flat music bed at -18 LU, and a master at -14 LUFS." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
    <http://ops-sys.local/ontology#concept/frame-checklist> rdf:type ops:Concept ;
      ops:name "Frame checklist" ;
      ops:conceptType "process" ;
      ops:summary "Quality gate for each frame: dense set, readable face, nothing floating, and every number landing as an object." ;
      ops:sourceDoc "cartoon3d/STYLE.md" .
